def normalize_product_prices(apps, schema_editor):
    Product = apps.get_model('shop', 'Product')
    Product.objects.filter(discounted_price=0).update(discounted_price=None)


def restore_product_prices(apps, schema_editor):
    Product = apps.get_model('shop', 'Product')
    Product.objects.filter(discounted_price__isnull=True).update(discounted_price=0)


def copy_legacy_product_images(apps, schema_editor):
    Product = apps.get_model('shop', 'Product')
    ProductImage = apps.get_model('shop', 'ProductImage')
    for product in Product.objects.exclude(image='').iterator():
        ProductImage.objects.get_or_create(
            product_id=product.pk,
            is_primary=True,
            defaults={
                'image': product.image.name,
                'alt_text': product.title,
                'sort_order': 0,
            },
        )


